  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."blocks"') AND con.confrelid = to_regclass('"ms"."users"') AND ARRAY(SELECT a.attname::text FROM pg_attribute a WHERE a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) ORDER BY a.attname::text COLLATE "C") = ARRAY['blocker_id']::text[]);
  IF v_n = 0 AND (SELECT count(*) FROM pg_attribute WHERE attrelid = to_regclass('"ms"."blocks"') AND attnum > 0 AND NOT attisdropped AND attname = ANY (ARRAY['blocker_id']::name[])) = 1 THEN
    missing := missing || E'\n  ' || 'line 141: cascade from ms.users: no foreign key of ms.blocks to ms.users on (blocker_id) deletes or changes rows of ms.blocks (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 141: cascade from ms.users: ' || v_n || ' foreign keys of ms.blocks to ms.users on (blocker_id) delete or change rows of ms.blocks: drop all but one [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."blocks"') AND con.confrelid = to_regclass('"ms"."users"') AND ARRAY(SELECT a.attname::text FROM pg_attribute a WHERE a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) ORDER BY a.attname::text COLLATE "C") = ARRAY['blocked_id']::text[]);
  IF v_n = 0 AND (SELECT count(*) FROM pg_attribute WHERE attrelid = to_regclass('"ms"."blocks"') AND attnum > 0 AND NOT attisdropped AND attname = ANY (ARRAY['blocked_id']::name[])) = 1 THEN
    missing := missing || E'\n  ' || 'line 142: cascade from ms.users: no foreign key of ms.blocks to ms.users on (blocked_id) deletes or changes rows of ms.blocks (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 142: cascade from ms.users: ' || v_n || ' foreign keys of ms.blocks to ms.users on (blocked_id) delete or change rows of ms.blocks: drop all but one [AZ625]';
  END IF;
  IF missing <> '' THEN RAISE EXCEPTION 'the policy does not match this database:%', missing; END IF;
END $chk$;

