-- What else may have changed when objects of a type did: the objects that read them through a relation (a
-- dot, inheritance, a group's members, a group inside a group), then those that read those, until nothing
-- is new. Past 1000 objects of a type: all of them ({*}), and all of what reads them. Each is
-- announced with the cause 'dependent'.
CREATE OR REPLACE FUNCTION authz_int.dependents(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_all boolean := '*' = ANY (p_ids);
  v_rows bigint; v_most int;
  -- for each type: the ids known (s), new in the last round (n), found in this one (x), how many were found (c),
  -- and whether it is all of them (a)
  s1 bigint[] := '{}'; n1 bigint[] := '{}'; x1 bigint[]; c1 int := 0; a1 boolean := false;  -- bot
  s2 bigint[] := '{}'; n2 bigint[] := '{}'; x2 bigint[]; c2 int := 0; a2 boolean := false;  -- chat
  s3 text[] := '{}'; n3 text[] := '{}'; x3 text[]; c3 int := 0; a3 boolean := false;  -- chat_bot
  s4 text[] := '{}'; n4 text[] := '{}'; x4 text[]; c4 int := 0; a4 boolean := false;  -- membership
  s5 text[] := '{}'; n5 text[] := '{}'; x5 text[]; c5 int := 0; a5 boolean := false;  -- message
  s6 uuid[] := '{}'; n6 uuid[] := '{}'; x6 uuid[]; c6 int := 0; a6 boolean := false;  -- user
BEGIN
  CASE p_type
    WHEN 'bot' THEN
      IF v_all THEN a1 := true;
      ELSE n1 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s1 := n1;
      END IF;
    WHEN 'chat' THEN
      IF v_all THEN a2 := true;
      ELSE n2 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s2 := n2;
      END IF;
    WHEN 'user' THEN
      IF v_all THEN a6 := true;
      ELSE n6 := ARRAY(SELECT DISTINCT x::uuid FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'uuid')); s6 := n6;
      END IF;
    ELSE RETURN;  -- nothing reads its objects
  END CASE;
  LOOP
    -- all of a type: all of what reads it too
    IF a1 THEN a3 := true; END IF;
    IF a2 THEN a3 := true; a4 := true; a5 := true; a6 := true; END IF;
    IF a6 THEN a4 := true; END IF;
    EXIT WHEN (a1 OR cardinality(n1) = 0) AND (a2 OR cardinality(n2) = 0) AND (a3 OR cardinality(n3) = 0) AND (a4 OR cardinality(n4) = 0) AND (a5 OR cardinality(n5) = 0) AND (a6 OR cardinality(n6) = 0);
    IF NOT a3 AND (cardinality(n1) > 0 OR cardinality(n2) > 0) THEN
      v_most := cardinality(s3) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (s3)), '{}')
        INTO v_rows, x3
        FROM (SELECT ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text FROM "ms"."chat_bots" x WHERE x."bot_id" = ANY (n1) AND cardinality(n1) > 0
          UNION ALL SELECT ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text FROM "ms"."chat_bots" x WHERE x."chat_id" = ANY (n2) AND cardinality(n2) > 0
          LIMIT v_most) d(v);
      a3 := v_rows >= v_most;
    ELSE
      x3 := '{}';
    END IF;
    IF NOT a4 AND (cardinality(n2) > 0 OR cardinality(n6) > 0) THEN
      v_most := cardinality(s4) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (s4)), '{}')
        INTO v_rows, x4
        FROM (SELECT ROW(x."chat_id"::bigint, x."user_id"::uuid)::text FROM "ms"."members" x WHERE x."chat_id" = ANY (n2) AND cardinality(n2) > 0
          UNION ALL SELECT ROW(x."chat_id"::bigint, x."user_id"::uuid)::text FROM "ms"."members" x WHERE x."user_id" = ANY (n6) AND cardinality(n6) > 0
          LIMIT v_most) d(v);
      a4 := v_rows >= v_most;
    ELSE
      x4 := '{}';
    END IF;
    IF NOT a5 AND (cardinality(n2) > 0) THEN
      v_most := cardinality(s5) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (s5)), '{}')
        INTO v_rows, x5
        FROM (SELECT ROW(x."chat_id"::bigint, x."seq"::bigint)::text FROM "ms"."messages" x WHERE x."chat_id" = ANY (n2) AND cardinality(n2) > 0
          LIMIT v_most) d(v);
      a5 := v_rows >= v_most;
    ELSE
      x5 := '{}';
    END IF;
    IF NOT a6 AND (cardinality(n2) > 0) THEN
      v_most := cardinality(s6) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (s6)), '{}')
        INTO v_rows, x6
        FROM (SELECT x."user_id" FROM "ms"."members" x WHERE x."chat_id" = ANY (n2) AND cardinality(n2) > 0
          LIMIT v_most) d(v);
      a6 := v_rows >= v_most;
    ELSE
      x6 := '{}';
    END IF;
    n1 := '{}';
    n2 := '{}';
    n3 := x3; s3 := s3 || x3; c3 := c3 + cardinality(x3); a3 := a3 OR c3 > 1000;
    n4 := x4; s4 := s4 || x4; c4 := c4 + cardinality(x4); a4 := a4 OR c4 > 1000;
    n5 := x5; s5 := s5 || x5; c5 := c5 + cardinality(x5); a5 := a5 OR c5 > 1000;
    n6 := x6; s6 := s6 || x6; c6 := c6 + cardinality(x6); a6 := a6 OR c6 > 1000;
  END LOOP;
  IF a3 AND NOT (v_all AND p_type = 'chat_bot') THEN
    PERFORM authz_int.announce('chat_bot', '{*}', 'dependent', false);
  ELSIF NOT a3 AND c3 > 0 THEN
    PERFORM authz_int.announce('chat_bot', ARRAY(SELECT v::text FROM unnest(s3[cardinality(s3) - c3 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a4 AND NOT (v_all AND p_type = 'membership') THEN
    PERFORM authz_int.announce('membership', '{*}', 'dependent', false);
  ELSIF NOT a4 AND c4 > 0 THEN
    PERFORM authz_int.announce('membership', ARRAY(SELECT v::text FROM unnest(s4[cardinality(s4) - c4 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a5 AND NOT (v_all AND p_type = 'message') THEN
    PERFORM authz_int.announce('message', '{*}', 'dependent', false);
  ELSIF NOT a5 AND c5 > 0 THEN
    PERFORM authz_int.announce('message', ARRAY(SELECT v::text FROM unnest(s5[cardinality(s5) - c5 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a6 AND NOT (v_all AND p_type = 'user') THEN
    PERFORM authz_int.announce('user', '{*}', 'dependent', false);
  ELSIF NOT a6 AND c6 > 0 THEN
    PERFORM authz_int.announce('user', ARRAY(SELECT v::text FROM unnest(s6[cardinality(s6) - c6 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
END $f$;

-- relationships kept in ms.members
CREATE OR REPLACE FUNCTION authz_int."rel_audit_4_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role = 'owner'), false)) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role = 'owner'), false)) c GROUP BY c.ot;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."rel_audit_4_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role = 'owner'), false)) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role = 'owner'), false)) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role = 'owner'), false)) c GROUP BY c.ot;
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role = 'owner'), false)) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'relate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'relate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true AND coalesce((role = 'owner'), false)) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role = 'owner'), false)) c GROUP BY c.ot;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."rel_audit_4_del"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role = 'owner'), false)) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."user_id"::text AS oid, 'in_chat' AS rel, 'chat' AS st, x."chat_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'admin' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role in ('admin', 'owner')), false) UNION ALL SELECT 'unrelate' AS action, 'chat' AS ot, x."chat_id"::text AS oid, 'owner' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM old_rows x WHERE true AND coalesce((role = 'owner'), false)) c GROUP BY c.ot;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."rel_audit_4_trunc"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    IF NOT authz_int.truncate_once(TG_RELID, 'rel_audit_4_trunc', TG_WHEN = 'BEFORE') THEN
      RETURN NULL;
    END IF;
    PERFORM authz_int.audit('truncate', 'chat', NULL, NULL, NULL, NULL, NULL, jsonb_build_object('table', pg_catalog.format('%I.%I', TG_TABLE_SCHEMA, TG_TABLE_NAME)));
    PERFORM authz_int.changed('chat', ARRAY['*'], 'relationship');
    PERFORM authz_int.audit('truncate', 'user', NULL, NULL, NULL, NULL, NULL, jsonb_build_object('table', pg_catalog.format('%I.%I', TG_TABLE_SCHEMA, TG_TABLE_NAME)));
    PERFORM authz_int.changed('user', ARRAY['*'], 'relationship');
  RETURN NULL;
END $f$;

-- user.in_chat.member
CREATE VIEW authz_int."user__in_chat__member" AS
  SELECT s."user_id" AS id FROM "ms"."members" s WHERE s."chat_id" IN (SELECT id FROM authz_int."chat__member");

-- user.see_phone (line 12): self or in_chat.member
CREATE VIEW authz_int."user__see_phone" AS
  (SELECT id FROM authz_int."user__self")
  UNION ALL
  (SELECT id FROM authz_int."user__in_chat__member");

CREATE OR REPLACE FUNCTION authz_gen."ms.users:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "ms"."users"; r_new "ms"."users";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for ms.users: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'ms.users', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT (jsonb_populate_record(NULL::"ms"."users", to_jsonb(x))).* INTO r_old FROM "ms"."people" x WHERE x."id" = p_id::uuid;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for ms.users: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."ms.users:update:why"(r_old, true)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."ms.users:update:why"(r_new, false) l) END;
END $f$;

-- ms.people: the rows of ms.users the user may select (line 69: signed_in)
-- mask phone (line 70): see_phone
-- @object view "ms"."people"
DO $mv$
DECLARE cols text; uses text;
BEGIN
  SELECT string_agg(CASE a.attname
      WHEN 'phone' THEN format('CASE WHEN %s THEN %I.%I END AS %I', '(coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."user__in_chat__member" v WHERE v.id = "users"."id"))', 'users', a.attname, a.attname)
      ELSE format('%I.%I', 'users', a.attname) END, ', ' ORDER BY a.attnum) INTO cols
  FROM pg_attribute a WHERE a.attrelid = '"ms"."users"'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  -- in place when it is there: what the app built on it (a view over it) goes on working
  BEGIN
    EXECUTE format('CREATE OR REPLACE VIEW "ms"."people" WITH (security_barrier) AS SELECT %s FROM "ms"."users" "users" WHERE %s',
                   cols, '(SELECT authz_int.scope_cmd(''ms.users'', ''select'')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false)');
  EXCEPTION WHEN invalid_table_definition THEN
    -- its columns are not the ones it had (the table's changed): made anew, unless something is built on it
    BEGIN
      DROP VIEW "ms"."people";
    EXCEPTION WHEN dependent_objects_still_exist THEN
      GET STACKED DIAGNOSTICS uses = PG_EXCEPTION_DETAIL;
      RAISE EXCEPTION 'the masked view ms.people can''t be replaced in place: the columns of ms.users changed, and something is built on the view [AZ617]'
        USING DETAIL = uses, HINT = 'drop what is built on it, apply (or run the migration) again, then make it again';
    END;
    EXECUTE format('CREATE VIEW "ms"."people" WITH (security_barrier) AS SELECT %s FROM "ms"."users" "users" WHERE %s',
                   cols, '(SELECT authz_int.scope_cmd(''ms.users'', ''select'')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false)');
  END;
END $mv$;
COMMENT ON VIEW "ms"."people" IS 'rowstile masked view';
REVOKE ALL ON "ms"."people" FROM PUBLIC;
GRANT SELECT ON "ms"."people" TO "ms_app";

-- Column privileges: masked columns are read through the masked view only. What masks took away is given
-- back first; then what this policy masks is taken away again
DO $mr$
DECLARE r record; cols text;
BEGIN
  FOR r IN SELECT * FROM authz.masked_tables LOOP
    IF to_regclass(r.tbl) IS NOT NULL AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN
      IF r.whole THEN
        -- (taking the table's SELECT back takes the SELECT on its other columns the mask gave instead)
        EXECUTE format('REVOKE SELECT ON %s FROM %I', r.tbl, r.role);
        EXECUTE format('GRANT SELECT ON %s TO %I', r.tbl, r.role);
      END IF;
      SELECT string_agg(format('%I', attname), ', ') INTO cols FROM pg_attribute
      WHERE attrelid = r.tbl::regclass AND attnum > 0 AND NOT attisdropped AND attname = ANY (r.cols);
      IF cols IS NOT NULL THEN EXECUTE format('GRANT SELECT (%s) ON %s TO %I', cols, r.tbl, r.role); END IF;
    END IF;
    DELETE FROM authz.masked_tables WHERE tbl = r.tbl AND role = r.role;
  END LOOP;
END $mr$;
DO $mc$
DECLARE cols text; whole boolean; took text[];
BEGIN
  -- ms.users: phone only through ms.people
  whole := has_table_privilege('ms_app', '"ms"."users"', 'SELECT');
  -- (the SELECT of their own the masked columns have, taken away below: given back when the mask goes)
  took := ARRAY(SELECT c FROM unnest(ARRAY['phone']) c
                WHERE NOT whole AND has_column_privilege('ms_app', '"ms"."users"', c, 'SELECT'));
  IF whole THEN
    REVOKE SELECT ON "ms"."users" FROM "ms_app";
    SELECT string_agg(format('%I', attname), ', ') INTO cols FROM pg_attribute
    WHERE attrelid = '"ms"."users"'::regclass AND attnum > 0 AND NOT attisdropped
      AND attname <> ALL (ARRAY['phone']);
    IF cols IS NOT NULL THEN EXECUTE format('GRANT SELECT (%s) ON "ms"."users" TO "ms_app"', cols); END IF;
  END IF;
  IF whole OR took <> '{}' THEN
    INSERT INTO authz.masked_tables VALUES ('"ms"."users"', 'ms_app', whole, took);
  END IF;
  REVOKE SELECT ("phone") ON "ms"."users" FROM "ms_app";
  IF has_column_privilege('ms_app', '"ms"."users"', 'phone', 'SELECT') THEN
    RAISE EXCEPTION 'ms_app could still read masked columns of ms.users directly [AZ611]'
      USING HINT = 'SELECT on the table or these columns is granted to PUBLIC or to a role ms_app belongs to; revoke it, then apply again';
  END IF;
END $mc$;

-- authz_int.masked_columns: its rows again
DELETE FROM authz_int.masked_columns;
INSERT INTO authz_int.masked_columns VALUES ('"ms"."users"', 'phone', '"ms"."people"');

-- A permission on an object, whether the user may select its row or not: what the functions that act on the
-- object ask (sharing, roles, keys, view_as, break_glass, requests), where authz.can's answer is for rows they may see
CREATE OR REPLACE FUNCTION authz_int.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_bigint bigint; v_text text; v_uuid uuid;
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "ms"."users" o WHERE o."id" = v_uuid AND (coalesce(o."id" = (SELECT authz.uid()), false)));
        WHEN 'see_phone' THEN RETURN EXISTS (SELECT 1 FROM "ms"."users" o WHERE o."id" = v_uuid AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."user__in_chat__member" v WHERE v.id = o."id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "ms"."bots" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))));
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "ms"."bots" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"))));
        WHEN 'post' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND (((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))));
        WHEN 'invite' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))));
        WHEN 'join' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND (((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))));
        WHEN 'setup' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = o.id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false))));
        WHEN 'add_members' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND (((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false)))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq") AND ((authz_int."message__check_522cac4d84"((o.*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = o."chat_id"))));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq") AND ((coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false))));
        WHEN 'remove' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq") AND ((coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = o."chat_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat_bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."chat_bot__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."chat_bot__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'block' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."block__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."block__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist, and on a table with a select rule only rows the user may select: a row they can't see
-- reads as a missing one; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint; v_text text; v_uuid uuid;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in). A check answers true or false; one that raises
    -- (a type or a permission the policy doesn't have) is not logged
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, v_allowed::text;
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "ms"."users" o WHERE o."id" = v_uuid AND (coalesce(o."id" = (SELECT authz.uid()), false))
    AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)));
        WHEN 'see_phone' THEN RETURN EXISTS (SELECT 1 FROM "ms"."users" o WHERE o."id" = v_uuid AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."user__in_chat__member" v WHERE v.id = o."id")))
    AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "ms"."bots" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false)))
    AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)));
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "ms"."bots" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false)))
    AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"))));
        WHEN 'post' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND (((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id")))
    AND (((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = o.id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false)))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))));
        WHEN 'invite' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    AND (((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = o.id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false)))));
        WHEN 'join' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND (((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))));
        WHEN 'setup' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND ((coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = o.id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false))));
        WHEN 'add_members' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = v_bigint AND (((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false))))
    AND (((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = o.id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false)))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq") AND ((authz_int."message__check_522cac4d84"((o.*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = o."chat_id"))));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq") AND ((coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false)))
    AND ((authz_int."message__check_522cac4d84"((o.*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = o."chat_id"))));
        WHEN 'remove' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq") AND ((coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = o."chat_id")))
    AND ((authz_int."message__check_522cac4d84"((o.*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = o."chat_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat_bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."chat_bot__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."chat_bot__key"::text;
