    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = o."chat_id")))
    AND ((authz_int."message__check_522cac4d84"((o.*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = o."chat_id"))))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Every object the user holds a permission on, whether they may select its row or not: what the access previews
-- (rowstile diff, the review's access, rowstile snapshot) list, run as the owner. authz.list where it is the same
CREATE OR REPLACE FUNCTION authz_int.list(p_type text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'user.edit' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE coalesce(o."id" = (SELECT authz.uid()), false);
    WHEN 'user.see_phone' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE (coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."user__in_chat__member" v WHERE v.id = o."id"));
    WHEN 'bot.manage' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
    WHEN 'bot.manage_keys' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
    WHEN 'chat.post' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"));
    WHEN 'chat.invite' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"));
    WHEN 'chat.add_members' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false)));
    WHEN 'message.edit' THEN
      RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
    WHEN 'message.remove' THEN
      RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = o."chat_id"));
    ELSE
      RETURN QUERY SELECT * FROM authz.list(p_type, p_perm);
  END CASE;
END $f$;

-- Every permission the user holds on one object: SELECT authz.perms('file', 11)
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE names text[];
BEGIN
  CASE p_type
    WHEN 'user' THEN names := ARRAY['edit', 'see_phone']::text[];
    WHEN 'bot' THEN names := ARRAY['manage', 'manage_keys']::text[];
    WHEN 'chat' THEN names := ARRAY['read', 'post', 'manage', 'invite', 'join', 'setup', 'add_members']::text[];
    WHEN 'membership' THEN names := ARRAY[]::text[];
    WHEN 'message' THEN names := ARRAY['read', 'edit', 'remove']::text[];
    WHEN 'chat_bot' THEN names := ARRAY[]::text[];
    WHEN 'block' THEN names := ARRAY[]::text[];
    ELSE RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  RETURN ARRAY(SELECT n FROM unnest(names) n WHERE authz.can(p_type, p_id, n));
END $f$;

CREATE FUNCTION authz_int."user__see_phone__who"(p_id uuid) RETURNS SETOF uuid
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."user__self__who"(p_id) x)
  UNION ALL
  (SELECT x FROM (SELECT s."chat_id" AS id FROM "ms"."members" s WHERE s."user_id" = p_id AND s."chat_id" IS NOT NULL) tg, LATERAL authz_int."chat__member__who"(tg.id) x)
$f$;

CREATE FUNCTION authz_int."user__see_phone__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."user__see_phone");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'user.see_phone = self or in_chat.member';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__self");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'self';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."user__self__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__in_chat__member");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'in_chat.member';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = tg.id) AS ok
               FROM (SELECT s."chat_id" AS id FROM "ms"."members" s WHERE s."user_id" = p_id AND s."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'chat', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'in_chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'in_chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has member' ELSE ', without member' END;
      IF NOT ('chat:member:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__member__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('chat:member:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_bigint bigint; v_text text; v_uuid uuid;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."user__edit__who"(v_uuid) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'see_phone' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."user__see_phone__who"(v_uuid) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."bot__manage__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage_keys' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."bot__manage_keys__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."chat__read__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'post' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."chat__post__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."chat__manage__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'invite' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."chat__invite__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'join' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."chat__join__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'setup' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."chat__setup__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'add_members' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."chat__add_members__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."message__read__who"(v_text) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."message__edit__who"(v_text) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'remove' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."message__remove__who"(v_text) x WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat_bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."chat_bot__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."chat_bot__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'block' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."block__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."block__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_bigint bigint; v_text text; v_uuid uuid;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), '');
        v_asker text[];   -- for another user: the one asking, whose sight the walk keeps to
BEGIN
  -- the signed-in user's own id is the signed-in user: asked as without it (a service whose id is a user's is not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS NOT DISTINCT FROM authz.uid()::text THEN
    p_user := NULL;
  END IF;
  -- another user's access: only for people who may inspect the object, within their scopes (as authz.who)
  IF p_user IS NOT NULL AND (NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm)) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  IF p_user IS NOT NULL THEN
    v_asker := ARRAY[v_me, v_pt, v_scopes];
    PERFORM set_config('authz.user_id', authz_int.canon('user', p_user), true);
    PERFORM set_config('authz.principal_type', '', true);
    PERFORM set_config('authz.scopes', '', true);   -- that user's access, with full rights (as authz.who)
    PERFORM authz_int.sign();
  END IF;
  v_ok := authz_int.can(p_type, p_id, p_perm);
  RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
    || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."user__edit__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'see_phone' THEN RETURN QUERY SELECT * FROM authz_int."user__see_phone__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."bot__manage__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'manage_keys' THEN RETURN QUERY SELECT * FROM authz_int."bot__manage_keys__why"(v_bigint, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN RETURN QUERY SELECT * FROM authz_int."chat__read__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'post' THEN RETURN QUERY SELECT * FROM authz_int."chat__post__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."chat__manage__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'invite' THEN RETURN QUERY SELECT * FROM authz_int."chat__invite__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'join' THEN RETURN QUERY SELECT * FROM authz_int."chat__join__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'setup' THEN RETURN QUERY SELECT * FROM authz_int."chat__setup__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'add_members' THEN RETURN QUERY SELECT * FROM authz_int."chat__add_members__why"(v_bigint, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN RETURN QUERY SELECT * FROM authz_int."message__read__why"(v_text, 1, '{}', v_asker);
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."message__edit__why"(v_text, 1, '{}', v_asker);
        WHEN 'remove' THEN RETURN QUERY SELECT * FROM authz_int."message__remove__why"(v_text, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat_bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."chat_bot__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."chat_bot__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'block' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."block__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."block__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('"ms_app"');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'ms_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'ms_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'ms_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- the policy's owner (or a member of it): its sessions are believed unsigned, it may read rowstile's tables
  -- (the session key among them) and turn row-level security off (applying refuses it, AZ624: this finds a grant made since)
  FOR r IN SELECT n.nspowner::regrole AS owner FROM pg_namespace n, pg_roles a
           WHERE n.nspname = 'authz_int' AND a.oid = v_role AND NOT a.rolsuper AND pg_has_role(v_role, n.nspowner, 'MEMBER') LOOP
    severity := 'error'; object := 'ms_app';
    problem := format('is the policy''s owner %s, or a member of it: who is signed in is believed without a signature, and it may read rowstile''s tables and turn row-level security off. The app role must be a role of its own: not the tables'' owner or the policy''s, nor a member of either', r.owner);
    RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"ms_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"ms_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."bot__manage"', 'authz_int."chat__add_members"', 'authz_int."chat__admin"', 'authz_int."chat__bot"', 'authz_int."chat__invitee"', 'authz_int."chat__join"', 'authz_int."chat__manage"', 'authz_int."chat__member"', 'authz_int."chat__owner"', 'authz_int."chat__post"', 'authz_int."chat__read"', 'authz_int."chat__setup"', 'authz_int."user__has_blocked"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"ms_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"ms_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"ms.blocks:delete:items"', '"ms.blocks:delete:why"', '"ms.blocks:insert:items"', '"ms.blocks:insert:refuse"', '"ms.blocks:insert:why"', '"ms.blocks:rules:explain"', '"ms.bots:column id, owner_id:items"', '"ms.bots:column id, owner_id:why"', '"ms.bots:delete:items"', '"ms.bots:delete:why"', '"ms.bots:insert:items"', '"ms.bots:insert:refuse"', '"ms.bots:insert:why"', '"ms.bots:rules:explain"', '"ms.bots:update:items"', '"ms.bots:update:refuse"', '"ms.bots:update:why"', '"ms.chat_bots:delete:items"', '"ms.chat_bots:delete:why"', '"ms.chat_bots:insert:items"', '"ms.chat_bots:insert:refuse"', '"ms.chat_bots:insert:why"', '"ms.chat_bots:rules:explain"', '"ms.chats:column kind, created_by, created_at, last_seq:items"', '"ms.chats:column kind, created_by, created_at, last_seq:why"', '"ms.chats:delete:items"', '"ms.chats:delete:why"', '"ms.chats:insert:items"', '"ms.chats:insert:refuse"', '"ms.chats:insert:why"', '"ms.chats:rules:explain"', '"ms.chats:update:items"', '"ms.chats:update:refuse"', '"ms.chats:update:why"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:items"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:why"', '"ms.members:column last_read_seq after:items"', '"ms.members:column last_read_seq after:why"', '"ms.members:column last_read_seq:items"', '"ms.members:column last_read_seq:why"', '"ms.members:column role after:items"', '"ms.members:column role after:why"', '"ms.members:column role:items"', '"ms.members:column role:why"', '"ms.members:delete:items"', '"ms.members:delete:why"', '"ms.members:insert:items"', '"ms.members:insert:refuse"', '"ms.members:insert:why"', '"ms.members:rules:explain"', '"ms.members:update:items"', '"ms.members:update:refuse"', '"ms.members:update:why"', '"ms.messages:column body after:items"', '"ms.messages:column body after:why"', '"ms.messages:column chat_id, seq, sender_id, bot_id, cr_cb6d8c70"', '"ms.messages:column chat_id, seq, sender_id, bot_id, cr_f7ab4c37"', '"ms.messages:column deleted after:items"', '"ms.messages:column deleted after:why"', '"ms.messages:column deleted:items"', '"ms.messages:column deleted:why"', '"ms.messages:column edited_at:items"', '"ms.messages:column edited_at:why"', '"ms.messages:delete:items"', '"ms.messages:delete:why"', '"ms.messages:insert:items"', '"ms.messages:insert:refuse"', '"ms.messages:insert:why"', '"ms.messages:rules:explain"', '"ms.messages:update:items"', '"ms.messages:update:refuse"', '"ms.messages:update:why"', '"ms.users:column id, phone, created_at:items"', '"ms.users:column id, phone, created_at:why"', '"ms.users:rules:explain"', '"ms.users:update:items"', '"ms.users:update:refuse"', '"ms.users:update:why"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"ms_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.list_links(text, uuid)', 'authz.revoke_link(text, uuid, text)', 'authz.create_link(text, uuid, text, timestamptz)', 'authz.create_role(text, uuid, text, text, text[])', 'authz.roles_of(text, uuid)', 'authz.request_access(text, uuid, text, text, interval)', 'authz.break_glass(text, uuid, text, text, interval)', 'authz.start_review(text, uuid, timestamptz)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, text, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, uuid, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.share(text, bigint, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, uuid, text)', 'authz.share(text, uuid, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, text, text)', 'authz.share(text, uuid, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, bigint, text)', 'authz.share(text, uuid, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, uuid, text)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowstile''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- the audit trail's guard, which fires in every replication role (ENABLE ALWAYS): ENABLE TRIGGER ALL, which a
  -- data-only pg_restore --disable-triggers ends with, puts it back for ordinary sessions only
  FOR r IN SELECT t.name, g.tgenabled::text AS mode
           FROM (VALUES ('authz_audit_append_only'), ('authz_audit_no_truncate')) t (name)
           LEFT JOIN pg_trigger g ON g.tgrelid = 'authz.audit'::regclass AND g.tgname = t.name
           WHERE g.tgenabled IS DISTINCT FROM 'A' LOOP
    severity := 'warning'; object := 'authz.audit';
    problem := format('the trigger %s %s. rowstile reapply puts it back, in every replication role', r.name,
      CASE r.mode
        WHEN 'O' THEN 'guards it in ordinary sessions only: one with session_replication_role = replica may change the trail (ENABLE TRIGGER ALL leaves it so, as at the end of a data-only pg_restore --disable-triggers)'
        WHEN 'R' THEN 'guards it with session_replication_role = replica only: an ordinary session may change the trail'
        WHEN 'D' THEN 'that guards it is off: the trail may be changed'
        ELSE 'that guards it is missing: the trail may be changed' END);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x) LOOP
    -- (FORCE ROW LEVEL SECURITY is no way out: an owner may turn it off again, and row-level security with it)
    IF pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('is owned by %s (or a role it belongs to): an owner skips row-level security, and may turn it off, FORCE ROW LEVEL SECURITY or not. The app role must not own the tables: ALTER TABLE %s OWNER TO the role that applies the policy', 'ms_app', r.tbl);
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'ms_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'ms_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'ms_app', r.tbl, 'ms_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowstile didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowstile''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'ms_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowstile''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'ms_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"', '"ms"."blocks"', '"ms"."chat_bots"', '"ms"."direct_blocks"', '"ms"."members"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"', '"ms"."blocks"', '"ms"."chat_bots"', '"ms"."direct_blocks"', '"ms"."members"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'ms_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules of the table above (apply turns
  -- row-level security on for the ones there are then; later ones are found here), and TRUNCATE skips the
  -- triggers for TRUNCATE alone that are not right there (the sync mirror's). The tables above: those
  -- with rules, and those rowstile watches (a trigger of its own on them)
  FOR r IN WITH RECURSIVE x(tbl, governed) AS (
             SELECT to_regclass(t), true FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) t
             UNION SELECT DISTINCT g.tgrelid::regclass, false FROM pg_trigger g
             JOIN pg_proc f ON f.oid = g.tgfoid AND f.pronamespace = 'authz_int'::regnamespace
             WHERE NOT g.tgisinternal AND g.tgrelid NOT IN (SELECT to_regclass(t) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) t
                                                           WHERE to_regclass(t) IS NOT NULL)
               AND NOT EXISTS (SELECT 1 FROM pg_description c WHERE c.objoid = g.oid AND c.classoid = 'pg_trigger'::regclass
                               AND c.description = 'rowstile: the trigger of the table above, for the rows stored here')),
           d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i JOIN x ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'ms_app', r.part, 'ms_app');
      RETURN NEXT;
    END IF;
    -- (on a table without rules, statements on it run the triggers of the table above as their own: the next loop
    -- finds one made since that lacks them)
    -- (one column's privilege is enough: no DELETE has columns)
    IF r.governed AND NOT r.relrowsecurity AND (has_any_column_privilege(v_role, r.part, 'INSERT') OR has_any_column_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE') OR has_any_column_privilege(v_role, r.part, 'SELECT')) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'ms_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- partitions and tables that inherit, made since the last apply: Postgres runs a table's row triggers for its
  -- own rows and its partitions' only, and its statement triggers for statements on it only; applying gives
  -- them to each table under it (whatever the app role may do there: the owner's statements count too, and
  -- rows written through the table above need no privilege of their own)
  FOR r IN SELECT c.child, k.relispartition AS part, (SELECT i.inhparent::regclass FROM pg_inherits i WHERE i.inhrelid = c.child LIMIT 1) AS above,
                  string_agg(c.name::text, ', ' ORDER BY c.name) AS names
           FROM authz_int.child_triggers() c JOIN pg_class k ON k.oid = c.child GROUP BY c.child, k.relispartition LOOP
    severity := 'error'; object := r.child::text;
    IF r.part THEN
      problem := format('is a partition of %s, and was made since the policy was last applied: Postgres runs a table''s statement triggers for statements on it only, so a statement on this partition doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    ELSE
      problem := format('inherits from %s, and was made since the policy was last applied: Postgres runs a table''s row triggers for its own rows only, and its statement triggers for statements on it only, so a rule on a column is not checked on the rows stored here, their shares stay when their key changes, and a statement on this table doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    END IF;
    RETURN NEXT;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             AND has_any_column_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a key column it may insert or update, not GENERATED ALWAYS; not one the
  -- index only INCLUDEs, which it holds but is not keyed by): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY ((i.indkey::int2[])[0:i.indnkeyatts - 1]) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'ms_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'ms_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.readers, v.typed
           FROM (VALUES ('"ms"."direct_blocks"', 'chat.blocked', false)) v(tbl, readers, typed) LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'ms_app', r.tbl, 'ms_app');
      RETURN NEXT;
    END IF;
    IF (has_any_column_privilege(v_role, r.tbl, 'INSERT') OR has_any_column_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'ms_app');
      RETURN NEXT;
    END IF;
    -- ... or read in full: who is linked to what (a type's table without rules is named above)
    IF NOT r.typed AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl)
       AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row, and the policy reads it for %s: who is linked to what is readable. Fine where that is no secret, otherwise give it a type and rules', 'ms_app', r.readers);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, what, loc, ask)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : %s"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.ask);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- rules for a command the app role has no privilege for (one column's is enough for a read, an insert or
  -- an update: the app may write some columns only)
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.cmd FROM (VALUES ('"ms"."blocks"', 'delete'), ('"ms"."blocks"', 'insert'), ('"ms"."blocks"', 'select'), ('"ms"."bots"', 'delete'), ('"ms"."bots"', 'insert'), ('"ms"."bots"', 'select'), ('"ms"."bots"', 'update'), ('"ms"."chat_bots"', 'delete'), ('"ms"."chat_bots"', 'insert'), ('"ms"."chat_bots"', 'select'), ('"ms"."chats"', 'delete'), ('"ms"."chats"', 'insert'), ('"ms"."chats"', 'select'), ('"ms"."chats"', 'update'), ('"ms"."members"', 'delete'), ('"ms"."members"', 'insert'), ('"ms"."members"', 'select'), ('"ms"."members"', 'update'), ('"ms"."messages"', 'insert'), ('"ms"."messages"', 'select'), ('"ms"."messages"', 'update'), ('"ms"."users"', 'select'), ('"ms"."users"', 'update')) v(tbl, cmd)
           WHERE v.tbl IS NOT NULL LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF r.cmd = 'delete' THEN
      CONTINUE WHEN has_table_privilege(v_role, r.tbl, 'DELETE');
    ELSE
      CONTINUE WHEN has_any_column_privilege(v_role, r.tbl, r.cmd);
    END IF;
    severity := 'warning'; object := r.tbl::text;
    problem := format('the policy has a rule for %s, but %s has no %s privilege on the table: the rule never applies, and the statement fails with Postgres''s own "permission denied for table". GRANT %s ON %s TO %s, or make the rule "%s : nobody"', r.cmd, 'ms_app', upper(r.cmd), upper(r.cmd), r.tbl, 'ms_app', r.cmd);
    RETURN NEXT;
  END LOOP;
  -- relations named like a type that signs in
  FOR r IN SELECT * FROM (VALUES ('chat', 'bot', 'relation chat.bot'), ('chat_bot', 'bot', 'relation chat_bot.bot')) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), which signs in: alone in a rule it reads like any %s, and it is this row''s. A name that says what the relation is (author, owner) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.rel);
    RETURN NEXT;
  END LOOP;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    -- (a composite key's columns are 'org_id, parent_id': any of them it may update)
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attnum > 0 AND NOT a.attisdropped
               AND a.attname::text = ANY (string_to_array(r.col, ', ')) AND has_column_privilege(v_role, r.tbl, a.attnum, 'UPDATE')) THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"', '"ms"."blocks"', '"ms"."chat_bots"', '"ms"."direct_blocks"', '"ms"."members"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') NOT IN ('rowstile masked view')
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_any_column_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'ms_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['ms.blocks', 'ms.bots', 'ms.chat_bots', 'ms.chats', 'ms.members', 'ms.messages', 'ms.users', 'ms.blocks', 'ms.chat_bots', 'ms.direct_blocks', 'ms.members']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"ms"."users"', 'id', 'user.self: find objects by id; user: find one by its key, for checks and write rules', NULL), ('"ms"."blocks"', 'blocker_id', 'user.has_blocked: find the members of an object; block.blocker: find objects by blocker_id', NULL), ('"ms"."blocks"', 'blocked_id', 'user.has_blocked: find what a subject is in', NULL), ('"ms"."members"', 'user_id', 'user.in_chat: find the members of an object; chat.member: find what a subject is in; chat.admin: find what a subject is in; chat.owner: find what a subject is in; membership.person: find objects by user_id', NULL), ('"ms"."members"', 'chat_id', 'user.in_chat: find what a subject is in; chat.member: find the members of an object; chat.admin: find the members of an object; chat.owner: find the members of an object; membership.chat: find objects by chat_id', NULL), ('"ms"."bots"', 'owner_id', 'bot.owner: find objects by owner_id', NULL), ('"ms"."bots"', 'id', 'bot: find one by its key, for checks and write rules', NULL), ('"ms"."chats"', 'created_by', 'chat.creator: find objects by created_by', NULL), ('"ms"."chat_bots"', 'chat_id', 'chat.bot: find the members of an object; chat_bot.chat: find objects by chat_id', NULL), ('"ms"."chat_bots"', 'bot_id', 'chat.bot: find what a subject is in; chat_bot.bot: find objects by bot_id', NULL), ('"ms"."direct_blocks"', 'chat_id', 'chat.blocked: find the members of an object', NULL), ('"ms"."direct_blocks"', 'user_id', 'chat.blocked: find what a subject is in', NULL), ('"ms"."chats"', 'id', 'chat: find one by its key, for checks and write rules', NULL), ('"ms"."members"', 'chat_id, user_id', 'membership: find one by its key, for checks and write rules', NULL), ('"ms"."messages"', 'chat_id', 'message.chat: find objects by chat_id', NULL), ('"ms"."messages"', 'sender_id', 'message.sender: find objects by sender_id', NULL), ('"ms"."messages"', 'bot_id', 'message.from_bot: find objects by bot_id', NULL), ('"ms"."messages"', 'chat_id, seq', 'message: find one by its key, for checks and write rules', NULL), ('"ms"."chat_bots"', 'chat_id, bot_id', 'chat_bot: find one by its key, for checks and write rules', NULL), ('"ms"."blocks"', 'blocker_id, blocked_id', 'block: find one by its key, for checks and write rules', NULL)) v(tbl, col, why, alone) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order), or what serves a (type, id)
    -- pair alone (its ids where they are two columns, its type where its id is one): a finished one, with no
    -- condition (the lookups are joins, which a partial index doesn't serve), as rowstile indexes counts them; its key
    -- columns only (an index on (a) INCLUDE (b) is not sorted by b)
    IF NOT EXISTS (SELECT 1 FROM pg_index i, unnest(ARRAY[r.col, r.alone]) w(cs)
                   WHERE w.cs IS NOT NULL AND i.indrelid = to_regclass(r.tbl) AND i.indisvalid AND i.indpred IS NULL
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:least(cardinality(string_to_array(w.cs, ', ')), i.indnkeyatts) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(w.cs, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

